const e=JSON.parse('{"key":"v-e704dac0","path":"/Projects-docs/Interview/%E4%BA%91%E5%8E%9F%E7%94%9F.html","title":"云原生","lang":"zh-CN","frontmatter":{"description":"云原生 Docker Docker 是一个开源的应用容器引擎，允许开发者打包他们的应用及依赖包到一个可移植的容器中，然后发布到任何流行的 Linux 机器上，也可以实现虚拟化。容器是完全使用沙盒机制，相互之间不会有任何接口。 了解容器的特性 轻量化 资源占用小：与传统的虚拟机相比，Docker 容器不需要额外负载一个完整的操作系统实例，因此占用的系统资源更少。容器直接运行在宿主机的内核上，不需要虚拟化层次，从而提供更高效的资源利用。 快速启动：由于不需要启动完整的操作系统，容器可以在几秒钟内启动。这为开发和部署提供了极大的灵活性和效率。 高效的系统资源利用：容器共享宿主机的操作系统内核，而不是每个容器都有自己的操作系统。这意味着它们占用更少的系统资源（如内存和处理能力）。","head":[["meta",{"property":"og:url","content":"https://ClearDewy.github.io/Projects-docs/Interview/%E4%BA%91%E5%8E%9F%E7%94%9F.html"}],["meta",{"property":"og:site_name","content":"Dewy-Wiki"}],["meta",{"property":"og:title","content":"云原生"}],["meta",{"property":"og:description","content":"云原生 Docker Docker 是一个开源的应用容器引擎，允许开发者打包他们的应用及依赖包到一个可移植的容器中，然后发布到任何流行的 Linux 机器上，也可以实现虚拟化。容器是完全使用沙盒机制，相互之间不会有任何接口。 了解容器的特性 轻量化 资源占用小：与传统的虚拟机相比，Docker 容器不需要额外负载一个完整的操作系统实例，因此占用的系统资源更少。容器直接运行在宿主机的内核上，不需要虚拟化层次，从而提供更高效的资源利用。 快速启动：由于不需要启动完整的操作系统，容器可以在几秒钟内启动。这为开发和部署提供了极大的灵活性和效率。 高效的系统资源利用：容器共享宿主机的操作系统内核，而不是每个容器都有自己的操作系统。这意味着它们占用更少的系统资源（如内存和处理能力）。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:updated_time","content":"2024-03-13T15:21:43.000Z"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:modified_time","content":"2024-03-13T15:21:43.000Z"}]]},"headers":[{"level":2,"title":"Docker","slug":"docker","link":"#docker","children":[{"level":3,"title":"了解容器的特性","slug":"了解容器的特性","link":"#了解容器的特性","children":[]},{"level":3,"title":"了解容器与虚拟机的区别","slug":"了解容器与虚拟机的区别","link":"#了解容器与虚拟机的区别","children":[]},{"level":3,"title":"掌握镜像打包、容器启动等基本使用","slug":"掌握镜像打包、容器启动等基本使用","link":"#掌握镜像打包、容器启动等基本使用","children":[]},{"level":3,"title":"了解docker网络模式","slug":"了解docker网络模式","link":"#了解docker网络模式","children":[]},{"level":3,"title":"了解底层Linux机制","slug":"了解底层linux机制","link":"#了解底层linux机制","children":[]}]},{"level":2,"title":"K8S（Kubernetes）基本概念","slug":"k8s-kubernetes-基本概念","link":"#k8s-kubernetes-基本概念","children":[{"level":3,"title":"了解k8s的功能，与docker的区别","slug":"了解k8s的功能-与docker的区别","link":"#了解k8s的功能-与docker的区别","children":[]},{"level":3,"title":"了解声明式API，不可变基础设施","slug":"了解声明式api-不可变基础设施","link":"#了解声明式api-不可变基础设施","children":[]},{"level":3,"title":"了解k8s整体架构和组件","slug":"了解k8s整体架构和组件","link":"#了解k8s整体架构和组件","children":[]},{"level":3,"title":"熟悉常用资源","slug":"熟悉常用资源","link":"#熟悉常用资源","children":[]},{"level":3,"title":"kuberctl 命令的基本使用","slug":"kuberctl-命令的基本使用","link":"#kuberctl-命令的基本使用","children":[]}]}],"git":{"createdTime":1710343303000,"updatedTime":1710343303000,"contributors":[{"name":"ClearDewy","email":"11166208+cleardewy@user.noreply.gitee.com","commits":1}]},"readingTime":{"minutes":21.92,"words":6575},"filePathRelative":"Projects-docs/Interview/云原生.md","localizedDate":"2024年3月13日","excerpt":"<h1> 云原生</h1>\\n<h2> Docker</h2>\\n<p>Docker 是一个开源的应用容器引擎，允许开发者打包他们的应用及依赖包到一个可移植的容器中，然后发布到任何流行的 Linux 机器上，也可以实现虚拟化。容器是完全使用沙盒机制，相互之间不会有任何接口。</p>\\n<h3> 了解容器的特性</h3>\\n<h4> 轻量化</h4>\\n<ul>\\n<li>\\n<p><strong>资源占用小</strong>：与传统的虚拟机相比，Docker 容器不需要额外负载一个完整的操作系统实例，因此占用的系统资源更少。容器直接运行在宿主机的内核上，不需要虚拟化层次，从而提供更高效的资源利用。</p>\\n</li>\\n<li>\\n<p><strong>快速启动</strong>：由于不需要启动完整的操作系统，容器可以在几秒钟内启动。这为开发和部署提供了极大的灵活性和效率。</p>\\n</li>\\n<li>\\n<p><strong>高效的系统资源利用</strong>：容器共享宿主机的操作系统内核，而不是每个容器都有自己的操作系统。这意味着它们占用更少的系统资源（如内存和处理能力）。</p>\\n</li>\\n</ul>","autoDesc":true}');export{e as data};
